    checkedOutOn: '2026-11-20',
    dueOn: '2026-11-27',
  });
  const store = sampleStore({ loans: [loan] });
  assert.equal(renewLoan(store, { loanId: 'loan_1', today: TODAY }).ok, true);
  assert.deepEqual(renewLoan(store, { loanId: 'loan_1', today: TODAY }), {
    ok: false,
    reason: 'renewal-limit',
  });
});

